{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C60"],
      "claim": "Meperidine, an N-methylpiperidine analogue, has an absolute oral bioavailability of about 52% in humans, supporting high F for the query's N-methylpiperidine core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Ketobemidone, another N-methylpiperidine opioid, has an absolute oral bioavailability of 34%, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Morphine, sharing the N-methylpiperidine motif, has an oral bioavailability of about 29% in healthy volunteers, above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Codeine, an N-methyl morphinan, has an oral bioavailability of about 84%, strongly above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Fenspiride, a spiro-piperidine ether-like drug, has almost complete oral bioavailability (90%), directly supporting high F for a spiro-piperidine ether.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Meptazinol, an N-methylpiperidine with a phenolic OH, has low absolute oral bioavailability (~8.7%), but its phenol-driven conjugation is absent in the query, limiting transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a small, rigid N-methylpiperidine spiro ether with no HBD and no phenol. The closest transferable analogues—meperidine, ketobemidone, morphine, codeine, and fenspiride—all show oral bioavailability above 20% (roughly 30–90%) despite basic amine ionization. The main negative analogue, meptazinol, owes its low F to phenolic conjugation, a feature absent in the query. Thus high F >=20% is better supported.",
  "evidence_gaps": [
    "No direct permeability or first-pass metabolism data for the exact query structure.",
    "Morgan similarities to evidence compounds are modest (<0.25), limiting structural transferability.",
    "Metabolic lability of the vinyl group and tertiary amine is uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

